<script setup>
import{computed,onMounted,ref}from'vue';import{AlertTriangle,CheckCircle2,LockKeyhole,RefreshCw,ShieldCheck}from'@lucide/vue';import{getM6EnterpriseWorkspace}from'../api/m6';import{createEnterpriseRiskReport,decideEnterpriseRisk,getEnterpriseRiskWorkspace}from'../api/enterpriseRisk';
const org=ref(''),data=ref(null),selected=ref(null),busy=ref(''),error=ref(''),reason=ref('已核对演示指标、样本门禁与风险证据');const metrics=computed(()=>selected.value?.metrics||[]);const pct=v=>v==null?'已抑制':`${(v*100).toFixed(1)}%`;function dates(){const e=new Date(),s=new Date(e);s.setDate(s.getDate()-30);return{period_start:s.toISOString(),period_end:e.toISOString()}}async function load(){busy.value='load';error.value='';try{if(!org.value){const x=await getM6EnterpriseWorkspace();org.value=x.selected?.organization_id||x.organizations?.[0]?.id||''}if(!org.value)throw new Error('请先准备企业培训样例');data.value=await getEnterpriseRiskWorkspace(org.value);selected.value=data.value.reports.find(x=>x.id===selected.value?.id)||data.value.reports[0]||null}catch(e){error.value=e.detail?.message||e.detail||e.message||'加载失败'}finally{busy.value=''}}async function create(){busy.value='create';try{const x=await createEnterpriseRiskReport({organization_id:org.value,...dates()});selected.value=x.report;await load()}catch(e){error.value=e.detail?.message||e.detail||'生成失败';busy.value=''}}async function act(action){busy.value=action;try{selected.value=await decideEnterpriseRisk(selected.value.id,{action,reason:reason.value,expected_version:selected.value.lock_version});await load()}catch(e){error.value=e.detail?.message||e.detail||'操作失败';busy.value=''}}onMounted(load)
</script>
<template><main class="risk-page"><header><div><p>ENTERPRISE RISK GOVERNANCE</p><h2>企业指标与匿名风险管理</h2><span>指标公式可解释、样本不足即抑制、风险只交由人工核对</span></div><button aria-label="刷新企业风险" @click="load"><RefreshCw :size="16"/></button></header><div class="truth"><ShieldCheck :size="17"/><div><strong>{{data?.truth_label||'可解释企业演示指标 · 非真实生产数据'}}</strong><span>{{data?.disclaimer}}</span></div></div><p v-if="error" class="error"><AlertTriangle :size="15"/>{{error}}</p>
<section class="dictionary"><h3>版本化指标字典</h3><div class="definitions"><article v-for="m in data?.metric_dictionary||[]" :key="m.key"><strong>{{m.name}}</strong><span>{{m.formula}}</span><small>阈值 {{m.direction==='gte'?'≥':'≤'}} {{m.unit==='ratio'?pct(m.threshold):m.threshold}} · {{m.threshold_basis}}</small><em>{{m.sources.join(' · ')}}</em></article></div></section>
<div class="toolbar"><button :disabled="Boolean(busy)" @click="create">生成近 30 天冻结报告</button><span>同组织、同窗口、同指标版本重复生成保持幂等。</span></div>
<section class="layout"><aside><h3>风险报告</h3><button v-for="x in data?.reports||[]" :key="x.id" :class="{active:selected?.id===x.id}" @click="selected=x"><strong>{{x.period.start.slice(0,10)}} → {{x.period.end.slice(0,10)}}</strong><span>{{x.status}} · 样本 {{x.privacy.population_size}}</span></button><p v-if="!data?.reports?.length">尚无报告</p></aside><div v-if="selected" class="detail"><div class="title"><div><h3>{{selected.metric_version}}</h3><span>内容哈希 {{selected.content_hash}}</span></div><em>{{selected.status}}</em></div><div class="privacy" :class="selected.privacy.sample_state"><LockKeyhole :size="16"/><div><strong>最小样本门禁：{{selected.privacy.sample_state}}</strong><span>样本 {{selected.privacy.population_size}} / 最低 {{selected.privacy.minimum_sample}}；不含姓名、账号或用户 ID，别名不可跨报告关联。</span></div></div><div class="metric-grid"><article v-for="m in metrics" :key="m.key"><strong>{{pct(m.value)}}</strong><span>{{m.name}}</span><em>{{m.state}}</em><small>{{m.formula}}</small></article></div><template v-if="selected.privacy.sample_state==='sufficient'"><h3>匿名人员下钻</h3><div class="people"><article v-for="x in selected.learners" :key="x.learner_alias"><strong>{{x.learner_alias}}</strong><span>培训 {{x.completed_assignments}}/{{x.training_assignments}} · 有效认证 {{x.active_certifications}} · 逾期复训 {{x.overdue_retraining_tasks}}</span><em>{{x.risk_level}}</em></article></div><h3>可解释风险项</h3><div v-for="x in selected.risks" :key="x.learner_alias" class="risk"><AlertTriangle :size="15"/><div><strong>{{x.learner_alias}} · {{x.risk_level}}</strong><span>{{x.evidence.join('；')}}</span><small>{{x.recommendation}}</small></div></div></template><p v-else class="suppressed">样本不足 3：指标值、分子分母、人员下钻与风险项全部抑制。</p><div v-if="selected.status!=='closed'" class="actions"><input v-model="reason" aria-label="企业风险处置理由"/><button v-if="selected.status==='open'" :disabled="Boolean(busy)" @click="act('acknowledge')"><CheckCircle2 :size="14"/>已知悉</button><button :disabled="Boolean(busy)" @click="act('close')">关闭报告</button></div><h3>人工责任记录</h3><div v-for="x in selected.decisions" :key="x.id" class="decision"><strong>{{x.action}} · {{x.from_status}} → {{x.to_status}}</strong><span>{{x.actor_role}} · {{x.actor_public_id}} · {{x.reason}}</span></div></div><div v-else class="empty">生成报告后查看指标与隐私门禁</div></section></main></template>
<style scoped>.risk-page{max-width:1180px;margin:0 auto;color:#26322b}header,.truth,.toolbar,.title,.privacy,.actions,.risk{display:flex;align-items:center}header{justify-content:space-between}header p{margin:0;color:#738078;font-size:10px;font-weight:800;letter-spacing:.12em}h2{margin:4px 0;font-size:24px}header span,.truth span,.toolbar span,.title span,.privacy span,.risk span,.decision span{display:block;color:#77857d;font-size:10px}header button{display:grid;width:36px;height:36px;place-items:center;border:1px solid #dce5de;border-radius:7px;background:#fff}.truth{gap:8px;margin:14px 0;padding:11px;border-left:3px solid #c6a35a;background:#fff8ec}.truth strong{font-size:11px}.dictionary,.detail,aside,.empty{padding:12px;border:1px solid #dee7e0;background:#fff}.dictionary h3,aside h3{margin:0 0 9px;font-size:12px}.definitions{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.definitions article{min-width:0;padding:9px;background:#f4f7f5}.definitions strong,.definitions span,.definitions small,.definitions em{display:block}.definitions strong{font-size:11px}.definitions span{margin:5px 0;font-size:9px;line-height:1.45}.definitions small{color:#7c6845;font-size:8px}.definitions em{margin-top:5px;color:#78847c;font-size:8px;font-style:normal}.toolbar{gap:10px;margin:10px 0}.toolbar button,.actions button{display:flex;align-items:center;gap:5px;padding:9px;border:0;border-radius:6px;background:#30443a;color:#fff}.toolbar button:disabled,.actions button:disabled{opacity:.45}.layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:10px}aside button{display:block;width:100%;padding:10px;border:0;border-bottom:1px solid #e7eee9;background:transparent;text-align:left}aside button.active{background:#eef5f0}aside strong,aside span{display:block;font-size:10px}.title{justify-content:space-between}.title h3{margin:0}.title span{overflow-wrap:anywhere}.title em{padding:4px 7px;background:#e8f1ea;font-size:10px;font-style:normal}.privacy{gap:8px;margin:10px 0;padding:10px;background:#edf6ef}.privacy.suppressed{background:#fff3df}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.metric-grid article{padding:10px;background:#f4f7f5}.metric-grid strong,.metric-grid span,.metric-grid em,.metric-grid small{display:block}.metric-grid strong{font-size:18px}.metric-grid span{font-size:10px}.metric-grid em{margin:4px 0;color:#8b6742;font-size:8px;font-style:normal}.metric-grid small{color:#758078;font-size:8px;line-height:1.4}.people{display:grid;grid-template-columns:repeat(2,1fr);gap:6px}.people article{position:relative;padding:9px;border:1px solid #e2eae4}.people strong,.people span{display:block;font-size:9px}.people em{position:absolute;right:8px;top:8px;color:#8b5a4d;font-size:8px}.risk{align-items:flex-start;gap:7px;padding:9px;border-top:1px solid #e7ede8}.risk strong,.risk small{display:block;font-size:9px}.risk small{margin-top:4px}.suppressed{padding:14px;background:#fff4e2;color:#765c35;font-size:10px}.actions{gap:7px;margin-top:10px}.actions input{min-width:0;flex:1;padding:8px;border:1px solid #dce5de;border-radius:6px}.decision{padding:8px;border-top:1px solid #e7ede8}.decision strong{font-size:10px}.empty{display:grid;min-height:260px;place-items:center;color:#7c8981}.error{display:flex;gap:6px;padding:8px;background:#fff0ed;color:#954c40;font-size:10px}@media(max-width:760px){.definitions,.metric-grid,.layout,.people{grid-template-columns:1fr}.toolbar,.actions{align-items:stretch;flex-direction:column}.title{align-items:flex-start;gap:7px}.dictionary{overflow:hidden}}</style>
